mapper.insert:
insert into student
(name, no, gender, phone, degree, clazz_id, create_time, update_time
, id_card
, is_college
, address
, graduation_date)
values
(#{name}, #{no}, #{gender}, #{phone}, #{degree}, #{clazzId}, #{createTime}, #{updateTime}
, #{idCard}
, #{isCollege}
, #{address}
, #{graduationDate})

mapper.update:
update student
name = #{name}, no = #{no}, gender = #{gender}, phone = #{phone}, degree = #{degree}, id_card = #{idCard}, is_college = #{isCollege}, address = #{address}, graduation_date = #{graduationDate}, clazz_id = #{clazzId}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select s.id, s.name, s.no, s.gender, s.phone, s.degree, s.id_card, s.is_college, s.address, s.graduation_date, s.violation_count, s.violation_score, s.clazz_id, s.create_time, s.update_time, c.name as clazzName from student s left join clazz c on s.clazz_id = c.id
and s.name like concat('%', #{name}, '%')
and s.degree = #{degree}
and s.clazz_id = #{clazzId}
order by s.update_time desc
